if (Test-Path $LocalBin) {
    $env:PATH = "$LocalBin;$env:PATH"
}

Write-Host "Workspace: $Root"
Write-Host "Target: Windows 11 x64"
Write-Host "Pinned commit: c1ec1915fc16f3dc1ec5d47d9a97f6210a574526"
Write-Host "Expected Node: 24.13.1"
Write-Host "Expected pnpm: 11.10.0"
if (-not (Test-Path (Join-Path $Root "source\SOURCE_LOCK.json"))) {
    Write-Warning "Source lock is missing. Run .\scripts\acquire_everything.ps1 before implementation."
}
if (Get-Command node -ErrorAction SilentlyContinue) { node --version }
if (Get-Command pnpm -ErrorAction SilentlyContinue) { pnpm --version }
if (Get-Command git -ErrorAction SilentlyContinue) { git --version }
Set-Location $Root

[CmdletBinding()]
param(
    [string]$OutputPath = ""
)

$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $PSScriptRoot
$Source = Join-Path $Root "source\primary"
if (-not (Test-Path (Join-Path $Source ".git"))) { throw "A Git source checkout is required." }
$commit = (& git -C $Source rev-parse HEAD).Trim()
if ($LASTEXITCODE -ne 0) { throw "Unable to read source commit." }
