Write-Host "SHA-256: $hash"

#!/usr/bin/env python3
import hashlib
import json
import shutil
import tarfile
import tempfile
from pathlib import Path, PurePosixPath

ROOT = Path(__file__).resolve().parents[1]
ARCHIVE = ROOT / "input" / "upstream_reference" / "published_runtime" / "t3-0.0.28.tgz"
OUTPUT = ROOT / "input" / "upstream_reference" / "reconstructed_runtime_source"
MANIFEST = OUTPUT / "REFERENCE_SOURCE_MANIFEST.json"

FIRST_PARTY_PREFIXES = (
    "src/",
    "apps/",
    "packages/",
    "scripts/",
    "infra/",
)
ROOT_FILES = {
    "vite.config.ts",
    "vitest.config.ts",
    "tsconfig.json",
    "package.json",
    "pnpm-workspace.yaml",
}
DENIED_PARTS = {"node_modules", ".git"}


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def normalize_source(source: str) -> str | None:
    value = source.replace("\\", "/")
    while value.startswith("../"):
        value = value[3:]
    if value.startswith("./"):
        value = value[2:]
    if not value:
        return None
    path = PurePosixPath(value)
    if path.is_absolute() or ".." in path.parts or any(part in DENIED_PARTS for part in path.parts):
        return None
    normalized = str(path)
    if normalized in ROOT_FILES or normalized.startswith(FIRST_PARTY_PREFIXES):
        return normalized
    return None


def read_sourcemaps() -> tuple[dict[str, bytes], dict[str, set[str]], list[dict]]:
    files: dict[str, bytes] = {}
    origins: dict[str, set[str]] = {}
    conflicts: list[dict] = []
    with tempfile.TemporaryDirectory(prefix="t3-runtime-reference-") as tmp:
        tmp_path = Path(tmp)
        with tarfile.open(ARCHIVE, "r:gz") as tar:
            members = tar.getmembers()
            for member in members:
                member_path = PurePosixPath(member.name)
                if member_path.is_absolute() or ".." in member_path.parts or member.issym() or member.islnk():
                    raise RuntimeError(f"Unsafe archive member: {member.name}")
            tar.extractall(tmp_path)

        maps = sorted((tmp_path / "package").rglob("*.map"))
        source_entries = 0
        first_party_entries = 0
        for map_path in maps:
            try:
                payload = json.loads(map_path.read_text(encoding="utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                continue
            sources = payload.get("sources") or []
            contents = payload.get("sourcesContent") or []
            if len(sources) != len(contents):
                continue
            relative_map = str(map_path.relative_to(tmp_path)).replace("\\", "/")
            for source, content in zip(sources, contents):
                source_entries += 1
                if not isinstance(source, str) or content is None:
                    continue
                normalized = normalize_source(source)
                if normalized is None:
                    continue
                first_party_entries += 1
                data = content.encode("utf-8") if isinstance(content, str) else json.dumps(content).encode("utf-8")
                if normalized in files and files[normalized] != data:
                    conflicts.append({
                        "path": normalized,
                        "existing_sha256": sha256_bytes(files[normalized]),
                        "conflicting_sha256": sha256_bytes(data),
                        "source_map": relative_map,
                    })
                    continue
                files.setdefault(normalized, data)
                origins.setdefault(normalized, set()).add(relative_map)
        stats = {
            "maps_scanned": len(maps),
            "source_entries_scanned": source_entries,
            "first_party_entries_scanned": first_party_entries,
        }
    return files, origins, conflicts, stats


def main() -> None:
    if not ARCHIVE.is_file():
        raise SystemExit(f"Missing runtime archive: {ARCHIVE}")
    files, origins, conflicts, stats = read_sourcemaps()
    if OUTPUT.exists():
        shutil.rmtree(OUTPUT)
    OUTPUT.mkdir(parents=True)
    records = []
    for relative in sorted(files):
        target = OUTPUT / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(files[relative])
        records.append({
            "path": relative,
            "sha256": sha256_bytes(files[relative]),
            "size_bytes": len(files[relative]),
            "source_maps": sorted(origins[relative]),
        })
    manifest = {
        "schema_version": 1,
        "classification": "reference_only_non_authoritative",
        "source_archive": str(ARCHIVE.relative_to(ROOT)).replace("\\", "/"),
        "source_archive_sha256": sha256_bytes(ARCHIVE.read_bytes()),
        "published_version": "0.0.28",
        "audited_commit": "c1ec1915fc16f3dc1ec5d47d9a97f6210a574526",
        "limitations": [
            "This source is reconstructed from published runtime sourcemaps, not an audited Git checkout.",
            "It may omit tests, migrations, assets, build scripts, native source, and unpublished files.",
            "It is 42 commits behind the audited commit and cannot authorize source mutation or completion claims.",
        ],
        "stats": {
            **stats,
            "files_written": len(records),
            "conflicts": len(conflicts),
        },
        "conflicts": conflicts,
        "files": records,
    }
    MANIFEST.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(f"Extracted {len(records)} reference-only first-party files; conflicts={len(conflicts)}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Fetch and immediately verify a complete exact-commit GitHub tree.

This script needs GitHub API transport. It never authorizes implementation by
itself; its output must pass import_verified_snapshot.py.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import os
import sys
import time
import urllib.error
import urllib.request
from pathlib import Path, PurePosixPath
from typing import Any

GIT_BLOB_MODES = {"100644", "100755", "120000"}


def git_blob_sha(data: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()


def safe_path(raw: str) -> PurePosixPath:
    path = PurePosixPath(raw)
    if not raw or "\x00" in raw or path.is_absolute() or ".." in path.parts:
        raise ValueError(f"unsafe Git path: {raw!r}")
    return path


class GitHubClient:
    def __init__(self, token: str | None, retries: int = 4) -> None:
        self.retries = retries
        self.headers = {
            "Accept": "application/vnd.github+json",
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "t3-agent-exact-snapshot-fetcher/1",
        }
        if token:
            self.headers["Authorization"] = f"Bearer {token}"

    def get_json(self, url: str) -> dict[str, Any]:
        delay = 1.0
        for attempt in range(self.retries):
            request = urllib.request.Request(url, headers=self.headers)
            try:
                with urllib.request.urlopen(request, timeout=60) as response:
                    return json.load(response)
            except urllib.error.HTTPError as exc:
                if exc.code not in {403, 429, 500, 502, 503, 504} or attempt + 1 == self.retries:
                    raise
                retry_after = exc.headers.get("Retry-After")
                time.sleep(float(retry_after) if retry_after else delay)
            except (urllib.error.URLError, TimeoutError):
                if attempt + 1 == self.retries:
                    raise
                time.sleep(delay)
            delay = min(delay * 2, 15)
        raise AssertionError("unreachable")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repository", default="pingdotgg/t3code")
    parser.add_argument("--commit", default="c1ec1915fc16f3dc1ec5d47d9a97f6210a574526")
    parser.add_argument("--output", type=Path, default=Path("input/upstream_reference/exact_snapshot"))
    parser.add_argument("--token-env", default="GITHUB_TOKEN")
    args = parser.parse_args()

    if "/" not in args.repository:
        raise SystemExit("--repository must be owner/name")
    owner, repo = args.repository.split("/", 1)
    output = args.output.resolve()
    state_path = output / "FETCH_STATE.json"
    blobs_dir = output / "blobs"
    output.mkdir(parents=True, exist_ok=True)
    blobs_dir.mkdir(parents=True, exist_ok=True)

    client = GitHubClient(os.environ.get(args.token_env))
    api = f"https://api.github.com/repos/{owner}/{repo}"
    try:
        commit_obj = client.get_json(f"{api}/git/commits/{args.commit}")
        verified_commit = client.get_json(f"{api}/commits/{args.commit}")
    except Exception as exc:
        raise SystemExit(f"GitHub API request failed before tree retrieval: {exc}")

    if commit_obj.get("sha") != args.commit or verified_commit.get("sha") != args.commit:
        raise SystemExit("GitHub returned the wrong commit")
    tree_sha = commit_obj.get("tree", {}).get("sha")
    if not isinstance(tree_sha, str) or len(tree_sha) != 40:
        raise SystemExit("commit tree SHA missing")

    tree = client.get_json(f"{api}/git/trees/{tree_sha}?recursive=1")
    if tree.get("sha") != tree_sha:
        raise SystemExit("recursive tree identity mismatch")
    if tree.get("truncated") is not False:
        raise SystemExit("GitHub recursive tree is truncated; refusing partial snapshot")

    entries: list[dict[str, Any]] = []
    for raw in tree.get("tree", []):
        if not isinstance(raw, dict):
            raise SystemExit("invalid tree entry")
        path = str(safe_path(str(raw.get("path", ""))))
        kind = raw.get("type")
        mode = raw.get("mode")
        sha = raw.get("sha")
        size = raw.get("size")
        if kind == "tree":
            entries.append({"path": path, "type": kind, "mode": mode, "sha": sha})
            continue
        if kind == "commit" or mode == "160000":
            raise SystemExit(f"submodule requires explicit handling: {path}")
        if kind != "blob" or mode not in GIT_BLOB_MODES:
            raise SystemExit(f"unsupported Git object: {path} type={kind} mode={mode}")
        if not isinstance(sha, str) or len(sha) != 40 or not isinstance(size, int):
            raise SystemExit(f"invalid blob metadata for {path}")
        entries.append({"path": path, "type": "blob", "mode": mode, "sha": sha, "size": size})

    existing_state: dict[str, Any] = {}
    if state_path.is_file():
        existing_state = json.loads(state_path.read_text(encoding="utf-8"))
    if existing_state and (
        existing_state.get("repository") != args.repository
        or existing_state.get("commit") != args.commit
        or existing_state.get("tree") != tree_sha
    ):
        raise SystemExit("existing fetch state belongs to another snapshot")

    completed: set[str] = set(existing_state.get("completedBlobs", []))
    blob_entries = [entry for entry in entries if entry["type"] == "blob"]
    for index, entry in enumerate(blob_entries, 1):
        sha = entry["sha"]
        destination = blobs_dir / sha
        if sha in completed and destination.is_file():
            data = destination.read_bytes()
            if len(data) == entry["size"] and git_blob_sha(data) == sha:
                continue
            completed.discard(sha)
        payload = client.get_json(f"{api}/git/blobs/{sha}")
        if payload.get("sha") != sha or payload.get("encoding") != "base64":
            raise SystemExit(f"invalid GitHub blob response for {sha}")
        try:
            data = base64.b64decode(str(payload.get("content", "")).encode(), validate=False)
        except Exception as exc:
            raise SystemExit(f"invalid base64 for {sha}: {exc}")
        if len(data) != entry["size"]:
            raise SystemExit(f"blob size mismatch for {entry['path']}")
        if git_blob_sha(data) != sha:
            raise SystemExit(f"blob SHA mismatch for {entry['path']}")
        temp = destination.with_suffix(".tmp")
        temp.write_bytes(data)
        temp.replace(destination)
        completed.add(sha)
        state_path.write_text(
            json.dumps(
                {
                    "schemaVersion": 1,
                    "repository": args.repository,
                    "commit": args.commit,
                    "tree": tree_sha,
                    "completedBlobs": sorted(completed),
                    "blobCount": len(blob_entries),
                },
                indent=2,
            )
            + "\n",
            encoding="utf-8",
        )
        if index % 100 == 0:
            print(f"verified {index}/{len(blob_entries)} blobs", file=sys.stderr)

    manifest = {
        "schemaVersion": 2,
        "repository": args.repository,
        "commit": args.commit,
        "tree": tree_sha,
        "parents": [parent.get("sha") for parent in commit_obj.get("parents", [])],
        "message": commit_obj.get("message"),
        "author": commit_obj.get("author"),
        "committer": commit_obj.get("committer"),
        "verification": verified_commit.get("commit", {}).get("verification"),
        "treeTruncated": False,
        "entries": entries,
        "acquisition": {
            "mode": "github_rest_recursive_tree_and_blobs",
            "allBlobHashesVerifiedDuringFetch": True,
        },
    }
    (output / "snapshot-manifest.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
    print(f"Fetched and verified {len(blob_entries)} blobs for {args.commit} tree {tree_sha}")


if __name__ == "__main__":
    main()
